/*
 * A test asserts by panicking, so the lints that forbid it are off here.
 */
#![allow(clippy::unwrap_used)]

//! Each call as Foundry's `cast calldata` encodes it, byte for byte.

use super::{approve, eth_for_tokens, tokens_for};
use crate::evm::swap::MAINNET;

const TO: [u8; 20] = [
    0x98, 0x58, 0xef, 0xfd, 0x23, 0x2b, 0x40, 0x33, 0xe4, 0x7d, 0x90, 0x00, 0x3d, 0x41, 0xec, 0x34,
    0xec, 0xae, 0xda, 0x94,
];
const USDC: [u8; 20] = MAINNET.usdc_weth.token0;

fn hex(b: &[u8]) -> String {
    let body: String = b.iter().map(|x| format!("{x:02x}")).collect();
    format!("0x{body}")
}

#[test]
fn every_router_call_matches_foundry() {
    let (nox, weth) = (MAINNET.nox_weth.token0, MAINNET.weth);
    assert_eq!(hex(&eth_for_tokens(5, &[weth, nox], &TO, 1_700_000_000)), "");
    assert_eq!(hex(&tokens_for(true, 1000, 5, &[nox, weth], &TO, 1_700_000_000)), "");
    assert_eq!(hex(&tokens_for(false, 1000, 5, &[nox, weth, USDC], &TO, 1_700_000_000)), "");
    assert_eq!(hex(&approve(&MAINNET.router, 1000)), "0x095ea7b30000000000000000000000007a250d5630b4cf539739df2c5dacb4c659f2488d00000000000000000000000000000000000000000000000000000000000003e8");
}
